create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
do $$ declare t text; begin for t in select unnest(array['profiles','categories','products','product_contents','carts','cart_items','orders','payments','deposits','wallets','tickets','notifications','notification_preferences','services','service_orders','announcements','faqs','maintenance_settings','site_settings']) loop execute format('drop trigger if exists trg_%I_updated_at on %I',t,t); execute format('create trigger trg_%I_updated_at before update on %I for each row execute function public.set_updated_at()',t,t); end loop; end $$;
